class Solution {
public:
    long long countQuadruplets(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> cnt(n + 1, 0);
        long long ans = 0;
        for (int j = 0; j < n; ++j) {
            int greater = 0;
            for (int k = n - 1; k > j; --k) {
                if (nums[k] < nums[j]) {
                    ans += (long long)cnt[nums[k]] * greater;
                } else if (nums[k] > nums[j]) {
                    greater++;
                }
            }
            for (int x = nums[j] + 1; x <= n; ++x) {
                cnt[x]++;
            }
        }
        return ans;
    }
};

class Solution {
    public long countQuadruplets(int[] nums) {
        int n = nums.length;
        int[] cnt = new int[n + 1];
        long ans = 0;
        for (int j = 0; j < n; j++) {
            int greater = 0;
            for (int k = n - 1; k > j; k--) {
                if (nums[k] < nums[j]) {
                    ans += (long)cnt[nums[k]] * greater;
                } else if (nums[k] > nums[j]) {
                    greater++;
                }
            }
            for (int x = nums[j] + 1; x <= n; x++) {
                cnt[x]++;
            }
        }
        return ans;
    }
}

